CREATE DATABASE Andrew_Pamela_Northwind_DB;

USE Andrew_Pamela_Northwind_DB;

CREATE TABLE Customers(Customer_ID VARCHAR(10) PRIMARY KEY,
    Company_Name VARCHAR(100) NOT NULL,
    Contact_Name VARCHAR(100) NOT NULL,
    Contact_Title VARCHAR(100) NOT NULL,
    Address VARCHAR(150) NOT NULL,
    City VARCHAR(50) NOT NULL,
    Region VARCHAR(50),
    Postal_Code VARCHAR(20) NOT NULL,
    Country VARCHAR(50) NOT NULL,
    Phone VARCHAR(30) NOT NULL,
    Fax VARCHAR(30));

CREATE TABLE Categories(Category_ID INT AUTO_INCREMENT PRIMARY KEY,
    Category_Name VARCHAR(100) NOT NULL,
    Description VARCHAR(255));

CREATE TABLE Employees(Employee_ID INT NOT NULL,
    Last_Name VARCHAR(50) NOT NULL,
    Order_ID INT,
    Customer_ID VARCHAR(10),
    Order_Date DATE,
    Ship_City VARCHAR(50),
    Product_ID INT,
    Product_Name VARCHAR(150),
    Discount DECIMAL(5,2),
    Unit_Price DECIMAL(10,2),
    Sales DECIMAL(12,2),
PRIMARY KEY (Employee_ID, Order_ID, Product_ID),FOREIGN KEY (Customer_ID)REFERENCES Customers(Customer_ID));
    
CREATE TABLE Suppliers(Supplier_ID INT AUTO_INCREMENT PRIMARY KEY,
    Company_Name VARCHAR(150) NOT NULL,
    Contact_Name VARCHAR(100) NOT NULL,
    Contact_Title VARCHAR(100) NOT NULL,
    Address VARCHAR(150) NOT NULL,
    City VARCHAR(50) NOT NULL,
    Region VARCHAR(50),
    Postal_Code VARCHAR(20) NOT NULL,
    Country VARCHAR(50) NOT NULL,
    Phone VARCHAR(30) NOT NULL,
    Fax VARCHAR(30),
    Home_Page VARCHAR(255));

CREATE TABLE Regions(Region_ID INT AUTO_INCREMENT PRIMARY KEY,
    Region_Description VARCHAR(100) NOT NULL);

CREATE TABLE Shippers(Shipper_ID INT AUTO_INCREMENT PRIMARY KEY,
    Company_Name VARCHAR(100) NOT NULL,
    Phone VARCHAR(30) NOT NULL);

CREATE TABLE Products(Product_ID INT AUTO_INCREMENT PRIMARY KEY,
    Product_Name VARCHAR(100) NOT NULL,
    Supplier_ID INT NOT NULL,
    Category_ID INT NOT NULL,
    Quantity_Per_Unit VARCHAR(50) NOT NULL,
    Unit_Price DECIMAL(10,2) NOT NULL,
    Units_In_Stock INT NOT NULL,
    Units_On_Order INT NOT NULL,
    Reorder_Level INT NOT NULL,
    Discontinued INT NOT NULL,
FOREIGN KEY (Supplier_ID)REFERENCES Suppliers(Supplier_ID),FOREIGN KEY (Category_ID)REFERENCES Categories(Category_ID));

CREATE TABLE Territories(Territory_ID INT AUTO_INCREMENT PRIMARY KEY,
Territory_Description VARCHAR(100) NOT NULL,
Region_ID INT NOT NULL,
FOREIGN KEY (Region_ID) REFERENCES Regions(Region_ID));

CREATE TABLE Employees_Territories(Employee_ID INT NOT NULL,
Territory_ID INT NOT NULL,
PRIMARY KEY (Employee_ID, Territory_ID),FOREIGN KEY (Territory_ID)REFERENCES Territories(Territory_ID));

CREATE TABLE Order_Details(Order_ID INT AUTO_INCREMENT PRIMARY KEY,
    Customer_ID VARCHAR(10) NOT NULL,
    Employee_ID INT NOT NULL,
    Order_Date DATE NOT NULL,
    Required_Date DATE NOT NULL,
    Shipped_Date VARCHAR(20),
    Ship_Via INT NOT NULL,
    Freight DECIMAL(10,2) NOT NULL,
    Ship_Name VARCHAR(100) NOT NULL,
    Ship_Address VARCHAR(150) NOT NULL,
    Ship_City VARCHAR(50) NOT NULL,
    Ship_Region VARCHAR(50),
    Ship_Postal_Code VARCHAR(20),
    Ship_Country VARCHAR(50) NOT NULL,
FOREIGN KEY (Customer_ID)
REFERENCES Customers(Customer_ID),FOREIGN KEY (Ship_Via)REFERENCES Shippers(Shipper_ID));

CREATE TABLE Orders
(Order_ID INT NOT NULL,
Product_ID INT NOT NULL,
Quantity INT NOT NULL,
Discount DECIMAL(5,2) NOT NULL,
PRIMARY KEY (Order_ID, Product_ID),FOREIGN KEY (Product_ID)REFERENCES Products(Product_ID));










